<script setup lang="ts">import {onMounted,ref} from 'vue';import {clone,getStudio,saveStudio,type StudioPayload} from './content-studio-api';const payload=ref<StudioPayload|null>(null),message=ref('');async function load(){payload.value=await getStudio()}onMounted(load);function add(){payload.value!.document.themes.push({id:`theme-${crypto.randomUUID()}`,name:{zh:'新主题',en:''},summary:{zh:'',en:''},icon:'地',tone:'#4f8f78',order:(payload.value!.document.themes.length+1)*10,published:false,archivedAt:null})}async function save(){const doc=clone(payload.value!.document);await saveStudio(payload.value!,doc,'themes','all','修改兴趣主题');message.value='主题草稿已保存，公开网站尚未改变。';await load()}</script>
<template><div v-if="payload" class="workspace-page studio-page"><div class="workspace-title"><div><p class="kicker">兴趣主题</p><h1>像 Explore 页面一样维护主题</h1><p>路线分组与兴趣主题彼此独立。主题编号由系统保管。</p></div><button class="primary-action" @click="add">＋ 新建主题</button></div><p v-if="message" class="inline-message">{{message}}</p><div class="studio-theme-grid"><article v-for="(theme,index) in payload.document.themes.filter(t=>!t.archivedAt).sort((a,b)=>a.order-b.order)" :key="theme.id"><span :style="{background:theme.tone}">{{theme.icon}}</span><input v-model="theme.name.zh" class="card-title-input"><input v-model="theme.name.en" placeholder="English"><textarea v-model="theme.summary.zh" placeholder="主题简介"></textarea><label>图标<input v-model="theme.icon" maxlength="2"></label><label>颜色<input v-model="theme.tone" type="color"></label><label class="inline-check"><input v-model="theme.published" type="checkbox">公开</label><div><button :disabled="index===0" @click="theme.order-=15">↑</button><button :disabled="index===payload.document.themes.length-1" @click="theme.order+=15">↓</button><button class="remove-button" @click="theme.archivedAt=new Date().toISOString()">归档</button></div></article></div><div class="editor-action-bar"><button class="primary-action" @click="save">保存主题草稿</button></div></div></template>
